(() => {
  const button=document.querySelector('#readBtn');
  if(!button)return;
  const val=id=>document.querySelector('#'+id)?.value||'';
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const topic=()=>document.querySelector('#topicChoice')?.dataset.value||'工作';
  const hkNow=()=>{const p=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Hong_Kong',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).formatToParts(new Date()).reduce((o,x)=>(o[x.type]=x.value,o),{});return `${p.year}-${p.month}-${p.day}T${p.hour}:${p.minute}`};
  const liuren=()=>{const raw=val('momentTime')||hkNow(),d=new Date(`${raw}+08:00`),hour=d.getHours(),shichen=Math.floor((hour+1)/2)%12+1;let month=d.getMonth()+1,day=d.getDate(),lunarBasis='公曆日期';try{if(window.Solar){const x=Solar.fromYmdHms(d.getFullYear(),d.getMonth()+1,d.getDate(),hour,d.getMinutes(),0).getLunar();month=Math.abs(x.getMonth());day=x.getDay();lunarBasis='農曆日期';}}catch(e){}const gods=['大安','留連','速喜','赤口','小吉','空亡'],m=(month-1)%6,dayPos=(m+day-1)%6,timePos=(dayPos+shichen-1)%6;return {raw,month,day,shichen,m,dayPos,timePos,god:gods[timePos],trace:`大安起正月 → 第 ${month} 月落 ${gods[m]} → 月上起第 ${day} 日落 ${gods[dayPos]} → 日上起第 ${shichen} 個時辰落 ${gods[timePos]}`,basis:lunarBasis};};
  const bazi=()=>{const d=val('birthDate'),t=val('birthTime')||'12:00',p=d?d.split('-'):[];if(!window.Solar||p.length!==3)return '八字：出生資料未能完成排盤。';try{const x=Solar.fromYmdHms(Number(p[0]),Number(p[1]),Number(p[2]),Number(t.slice(0,2)),Number(t.slice(3,5)),0).getLunar().getEightChar();return `八字實算：年柱 ${x.getYear()}｜月柱 ${x.getMonth()}｜日柱 ${x.getDay()}｜時柱 ${x.getTime()}｜日主 ${x.getDayGan()}｜納音 ${x.getYearNaYin()}／${x.getMonthNaYin()}／${x.getDayNaYin()}／${x.getTimeNaYin()}`;}catch(e){return `八字：排盤失敗（${e.message}）。`;}};
  const meihua=()=>{const raw=val('momentTime')||hkNow(),d=new Date(`${raw}+08:00`),hour=d.getHours(),shichen=Math.floor((hour+1)/2)%12+1,n=Number(val('numbers'))||((d.getFullYear()+d.getMonth()+1+d.getDate())%997),digits=String(Math.abs(n)).split('').reduce((a,b)=>a+Number(b),0),upper=(n%8)||8,lower=(digits%8)||8,moving=(n%6)||6,names=['坤','乾','兌','離','震','巽','坎','艮'];return `梅花易數實算：起卦時間 ${raw}（香港時間）｜上卦 ${names[upper-1]}（${upper}）｜下卦 ${names[lower-1]}（${lower}）｜動爻 第 ${moving} 爻｜${val('numbers')?'按輸入數字起卦':'按時間起卦'}。`};
  const renderComprehensive=()=>{const x=liuren(),question=val('question').trim()||'目前最重要的選擇',result=document.querySelector('#resultText'),title=document.querySelector('#resultTitle'),host=document.querySelector('#interactiveResult');if(!result||!title)return;title.textContent='綜合解讀 · 八法合參';result.textContent=`問題：「${question}」\n\n綜合解讀唔會將八門結果全部當成答案，而係先逐門計算，再比較共同訊號。\n\n【出生命盤】\n${bazi()}\n\n【當下梅花】\n${meihua()}\n\n【小六壬實算】\n起卦時間：${x.raw}（香港時間）\n${x.basis}：${x.month} 月 ${x.day} 日｜時辰數 ${x.shichen}\n${x.trace}\n最後落宮：${x.god}\n\n【交叉判讀】\n長期命盤用來看你嘅慣性與承受方式；梅花用來看今次問題點樣變；小六壬用來看短期應追、應等、應避。三者如果唔一致，保留不確定，先以現實證據覆核。\n\n針對「${topic()}」：先完成一個 24 小時內可核對嘅行動，再於 7 日後按實際回覆更新判斷。\n\n注意：以上係命理推測與行動框架，唔係百分百預言。`;if(host){host.hidden=false;host.innerHTML=`<div class="ledger-result"><p class="eyebrow">CALCULATION LEDGER · ${esc(topic())}</p><h4>三層計算已完成</h4><div><b>八字</b><span>${esc(bazi())}</span></div><div><b>梅花易數</b><span>${esc(meihua())}</span></div><div><b>小六壬</b><span>${esc(x.god)}｜${esc(x.trace)}</span></div><p class="ledger-note">綜合解讀只會將已計算結果交叉比較，不會把未計算嘅內容當成結果。</p></div>`;}}
  button.addEventListener('click',()=>setTimeout(()=>{if(document.querySelector('.method.active')?.dataset.name==='綜合解讀')renderComprehensive();},180));
})();
